{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Cetirizine, a zwitterionic piperazine with a carboxylic acid and basic amine, showed brain-to-free-plasma ratios of only 0.16-0.49 in mice after i.v. injection, indicating impaired brain penetration; this directly supports a fail prediction for the similarly zwitterionic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Levocetirizine, another zwitterionic acid/amine antihistamine, had the lowest cerebral H1-receptor occupancy by PET and low BBB crossing, supporting inadequate CNS access for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Bepotastine, a zwitterionic piperidine acid, showed only 16.6% brain H1 receptor occupancy in human PET and was classified low permeability, supporting fail.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Cetirizine's very low brain concentration after i.v. dosing is attributed to P-gp-mediated efflux at the BBB, a relevant liability for the query's ionizable acid/amine structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A high-transfer sufentanil analogue showed CSF concentrations below detection after i.v. dosing, providing additional direct evidence of poor CNS exposure despite lipophilic character.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "A high-transfer benztropine analogue (3-[18F]FEPB) showed low non-receptor-mediated brain uptake in rodents, supporting fail.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "A zwitterionic piperidine-acid analogue showed a CSF/unbound-plasma ratio of 0.7 and acceptable passive permeability in rats, demonstrating that some zwitterionic molecules can achieve meaningful CNS access and contradicting a blanket fail.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C12"],
      "claim": "PET in volunteers showed cetirizine can cross the BBB and occupy about 30% of cortical H1 receptors, indicating some CNS access despite low brain/plasma ratios.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a fully ionized zwitterion with very low estimated logD and high MW, and the most structurally relevant direct evidence—cetirizine, levocetirizine, and bepotastine—shows poor brain/CSF exposure and efflux liability. One zwitterionic piperidine-acid analogue achieved good CSF/plasma, but the preponderance of transferable experimental evidence and the query's unfavorable physicochemical profile support inadequate CNS access.",
  "evidence_gaps": [
    "No direct brain, CSF, or plasma measurement exists for the query molecule.",
    "The positive zwitterionic analogue (C09) may differ in lipophilic substitution and size, limiting transfer.",
    "P-gp/BCRP substrate status of the query is not experimentally known.",
    "Species differences between rat, mouse, and human CNS exposure measurements add uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

